assert len(R) == 45

rows = []
for i, r in enumerate(R):
    n = i + 2
    rid, name = r[0], r[1]
    industry = f'=IFERROR(VLOOKUP($A{n},CLASSIFICATION!$A$2:$C$46,3,FALSE),"Unknown")'
    rows.append([rid, name, industry] + list(r[2:]))
assert all(len(x) == len(HEADER) for x in rows)
last = len(rows) + 1

INDS = ["Home Services","Dental","Medical","Healthcare","Automotive","Retail","Financial Services","Insurance","Hospitality","Real Estate","B2B Services","Education","Professional Services","Technology","Other","Unknown"]
FITS = ["Excellent","Strong","Moderate","Weak","Poor","Unknown"]
W = len(HEADER)
def pad(*vals): return list(vals) + [None] * (W - len(vals))
payload = [HEADER] + rows + [[None]*W]
h = len(payload) + 1
payload.append(pad("Industry-level summary", "Records", "Avg search intent", "Avg commercial intent", "Excellent", "Strong", "Moderate", "Weak", "Poor", "Unknown fit"))
first = len(payload) + 1
for ind in INDS:
    r = len(payload) + 1
    payload.append(pad(ind,
        f'=COUNTIF($C$2:$C${last},$A{r}&"*")',
        f'=IFERROR(ROUND(AVERAGEIF($C$2:$C${last},$A{r}&"*",$D$2:$D${last}),1),"-")',
        f'=IFERROR(ROUND(AVERAGEIF($C$2:$C${last},$A{r}&"*",$F$2:$F${last}),1),"-")',
        *[f'=COUNTIFS($C$2:$C${last},$A{r}&"*",$Q$2:$Q${last},"{f}")' for f in FITS]))
lastind = len(payload)
payload.append(pad("Total", f"=SUM(B{first}:B{lastind})", f'=IFERROR(ROUND(AVERAGE($D$2:$D${last}),1),"-")', f'=IFERROR(ROUND(AVERAGE($F$2:$F${last}),1),"-")', *[f"=SUM({c}{first}:{c}{lastind})" for c in "EFGHIJ"]))
payload.append([None]*W)
payload.append(pad("Google Ads fit distribution", "Records", "Prospects (P)", "Internal (I)"))
for f in FITS:
    r = len(payload) + 1
    payload.append(pad(f, f'=COUNTIF($Q$2:$Q${last},$A{r})', f'=COUNTIFS($Q$2:$Q${last},$A{r},$A$2:$A${last},"P-*")', f'=COUNTIFS($Q$2:$Q${last},$A{r},$A$2:$A${last},"I-*")'))

def cell(v):
    if v is None or isinstance(v, (int, float)): return v
    s = str(v)
    if s.startswith("="): return s
    if s[:1] in "+-(0123456789'": return "'" + s
    return s
sheet_payload = [[cell(v) for v in row] for row in payload]
with open(os.path.join(SP, "fit_lines.jsonl"), "w", encoding="utf-8") as fh:
    fh.write(chr(10).join(json.dumps(r, ensure_ascii=False) for r in sheet_payload))
with open(os.path.join(PROJ, "google_ads_fit.csv"), "w", newline="", encoding="utf-8") as fh:
    w = csv.writer(fh); w.writerow(HEADER); w.writerows(rows)

print("payload rows:", len(sheet_payload), "cols:", W, "data rows:", len(rows))
print("FIT all:", dict(Counter(r[16] for r in rows)), "| prospects:", dict(Counter(r[16] for r in rows if r[0].startswith("P"))))
print("URGENCY:", dict(Counter(r[9] for r in rows)))
print("GEO targeting:", dict(Counter(r[11] for r in rows)))
print("VALUE:", dict(Counter(r[7] for r in rows)))
print("COMPETITION:", dict(Counter(r[14] for r in rows)))
num = [(r[3], r[5]) for r in rows if isinstance(r[3], int)]
print("avg search:", round(sum(a for a, b in num)/len(num), 1), "avg commercial:", round(sum(b for a, b in num)/len(num), 1), "n=", len(num))
conv = Counter(c.split(" (")[0].strip() for r in rows for c in r[13].split(";"))
print("CONVERSIONS:", dict(conv))
